css:
.hst-doc { font-family: Arial, "Noto Sans Ethiopic", "Nyala", sans-serif; color: #0f172a; font-size: 11px; line-height: 1.35; border: 1px solid #1e293b; }
.hst-doc * { box-sizing: border-box; }
.hst-muted { color: #64748b; font-size: 10px; }
.hst-num { text-align: right; }
.hst-head { display: flex; border-bottom: 1px solid #1e293b; }
.hst-logo { width: 150px; border-right: 1px solid #1e293b; display: flex; align-items: center; justify-content: center; padding: 10px; font-weight: 700; }
.hst-logo img { max-width: 110px; max-height: 64px; object-fit: contain; }
.hst-head-title { flex: 1 1 0%; border-right: 1px solid #1e293b; text-align: center; padding: 8px 12px; }
.hst-head-title div:first-child { font-weight: 600; }
.hst-head-title div:last-child { font-weight: 700; }
.hst-meta { width: 250px; padding: 10px 12px; font-size: 11px; }
.hst-meta-row { color: #64748b; margin-bottom: 2px; }
.hst-meta-line { display: flex; justify-content: space-between; gap: 12px; padding: 2px 0; }
.hst-meta-line strong { font-weight: 700; text-decoration: underline; }
.hst-title-row { display: flex; border-bottom: 1px solid #1e293b; padding: 8px 14px; gap: 12px; }
.hst-title { flex: 1 1 0%; }
.hst-title > div { text-align: center; color: #334155; }
.hst-title > div:nth-child(2) { font-weight: 600; margin-bottom: 4px; }
.hst-saletype { margin-bottom: 6px; }
.hst-irn, .hst-sysno { margin-bottom: 4px; text-align: left; }
.hst-irn-val { color: #30479C; border-bottom: 1px solid #cbd5e1; word-break: break-all; }
.hst-qr img { width: 170px; height: 170px; background: #fff; padding: 4px; object-fit: contain; }
.hst-parties { display: flex; border-bottom: 1px solid #1e293b; }
.hst-party { flex: 1 1 0%; }
.hst-party:first-child { border-right: 1px solid #1e293b; }
.hst-party-head { background: #f1f5f9; border-bottom: 1px solid #cbd5e1; padding: 8px 12px; font-weight: 700; font-size: 12px; }
.hst-party-body { padding: 8px 12px; }
.hst-fl { color: #475569; font-size: 10px; }
.hst-field { display: flex; justify-content: space-between; gap: 16px; margin-bottom: 4px; border-bottom: 1px solid #94a3b8; padding-bottom: 3px; min-height: 16px; font-weight: 600; }
.hst-add-label { font-weight: 700; margin-bottom: 3px; }
.hst-items { width: 100%; border-collapse: collapse; }
.hst-items thead { background: rgba(48, 71, 156, 0.05); border-bottom: 2px solid #30479C; }
.hst-items th { padding: 8px; text-align: left; vertical-align: top; font-size: 10px; font-weight: 700; }
.hst-items th.hst-num, .hst-items td.hst-num { text-align: right; }
.hst-items td { padding: 10px 8px; border-top: 1px solid #cbd5e1; vertical-align: top; }
.hst-totals { border-bottom: 1px solid #1e293b; }
.hst-trow { display: flex; justify-content: flex-end; align-items: center; gap: 24px; border-top: 1px solid #cbd5e1; padding: 4px 12px; font-weight: 500; }
.hst-trow span:last-child { min-width: 120px; text-align: right; }
.hst-grand { background: rgba(48, 71, 156, 0.06); font-weight: 700; }
.hst-words { background: #f8fafc; padding: 8px 12px; border-bottom: 1px solid #1e293b; }
.hst-words-val { font-weight: 700; font-style: italic; }
.hst-foot-cols { display: flex; }
.hst-foot-col { flex: 1 1 0%; }
.hst-foot-col + .hst-foot-col { border-left: 1px solid #1e293b; }
.hst-foot-head { background: #f1f5f9; border-bottom: 1px solid #cbd5e1; border-top: 1px solid #1e293b; padding: 8px 12px; font-weight: 700; font-size: 12px; }
.hst-foot-body { padding: 12px; }
.hst-sign { border-bottom: 1px solid #94a3b8; padding-bottom: 3px; min-height: 16px; font-weight: 600; margin-top: 4px; }
.hst-thanks { text-align: center; font-style: italic; font-weight: 700; padding: 10px 12px; border-top: 1px solid #1e293b; }
